'use strict';
const $=id=>document.getElementById(id), KEY='shixu-projects-v1';
const samples=[{name:'个人项目看板',description:'给想法一个落脚点，搭建属于自己的项目管理空间。下一步：创建你的第一个真实项目。',status:'active',priority:'high',tags:['个人工具','Web 开发'],due:'',link:''},{name:'整理我的知识库',description:'把零散的笔记和收藏整理起来，建立一个更容易查找、持续积累的知识系统。',status:'todo',priority:'medium',tags:['学习','知识管理'],due:'',link:''},{name:'每周运动计划',description:'从每周三次运动开始，找到适合自己的节奏，记录每一次微小的进步。',status:'todo',priority:'low',tags:['生活','健康'],due:'',link:''},{name:'云环境初体验',description:'连接 GitHub 仓库，启动云环境，把第一个小想法变成可以使用的网页。',status:'done',priority:'medium',tags:['探索','已解锁'],due:'',link:''}].map((p,i)=>({...p,id:crypto.randomUUID(),createdAt:new Date(Date.now()-i*86400000).toISOString()}));
let projects=[],filter='all',editing=null,deleting=null,timer;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('toast').hidden=true,3500)}
function valid(p){return p&&typeof p.name==='string'&&p.name.trim()&&p.name.length<=80&&['todo','active','done'].includes(p.status)&&['low','medium','high'].includes(p.priority)&&Array.isArray(p.tags)&&p.tags.length<=10&&p.tags.every(t=>typeof t==='string'&&t.length<=100)&&typeof p.description==='string'&&p.description.length<=600&&typeof p.due==='string'&&(!p.due||/^\d{4}-\d{2}-\d{2}$/.test(p.due))&&(p.completedAt==null||WeeklyReport.validDate(p.completedAt))&&typeof p.link==='string'&&(!p.link||/^https?:\/\//i.test(p.link))}
function save(next){try{localStorage.setItem(KEY,JSON.stringify(next));projects=next;render();return true}catch(e){toast('未能保存：浏览器存储已满或不可用。请导出备份。');return false}}
try{const raw=localStorage.getItem(KEY);if(raw===null){projects=samples;localStorage.setItem(KEY,JSON.stringify(projects))}else{const data=JSON.parse(raw);if(!Array.isArray(data)||!data.every(valid))throw Error('invalid');projects=data}}catch(e){toast('无法读取本地数据。原数据未被覆盖，请检查浏览器存储设置。')}
function node(tag,className,text){const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=text;return el}
function today(){return WeeklyReport.today()}
function render(){const done=projects.filter(p=>p.status==='done').length,rate=projects.length?Math.round(done/projects.length*100):0;$('total').textContent=projects.length;$('countBadge').textContent=projects.length;$('activeCount').textContent=projects.filter(p=>p.status==='active').length;$('doneCount').textContent=done;$('rateLabel').textContent=rate+'%';$('rateBar').style.width=rate+'%';$('rateText').textContent=projects.length?`已完成 ${done} / ${projects.length} 个项目，继续保持`:'从一个小目标开始';const query=$('search').value.trim().toLowerCase();const visible=projects.filter(p=>(filter==='all'||p.status===filter)&&[p.name,p.description,...p.tags].join(' ').toLowerCase().includes(query));$('grid').replaceChildren(...visible.map(card));$('empty').hidden=visible.length>0;$('emptyText').textContent=projects.length?'没有找到匹配的项目，试试其他关键词或状态。':'新建一个项目，让想法开始发生。';$('emptyAdd').hidden=projects.length>0;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter))}
function card(p){const c=node('article','card'),top=node('div','card-top');top.append(node('div','project-icon',p.status==='done'?'✓':p.status==='active'?'▦':'◇'),node('span','priority '+p.priority,{high:'高优先级',medium:'中优先级',low:'低优先级'}[p.priority]));c.append(top,node('h3','',p.name),node('p','',p.description||'还没有描述，点击编辑补充你的计划。'));const tags=node('div','tags');p.tags.forEach(t=>tags.append(node('span','tag',t)));c.append(tags);const bottom=node('div','card-bottom'),select=node('select','status-select '+p.status);select.setAttribute('aria-label',p.name+'的状态');[['todo','待开始'],['active','进行中'],['done','已完成']].forEach(([value,label])=>{const o=node('option','',label);o.value=value;select.append(o)});select.value=p.status;select.addEventListener('change',()=>{if(save(projects.map(x=>x.id===p.id?{...x,status:select.value,completedAt:WeeklyReport.completedDate(x,select.value)}:x)))toast('项目状态已更新');else select.value=p.status});bottom.append(select);const overdue=p.due&&p.due<today()&&p.status!=='done';bottom.append(node('span','date'+(overdue?' overdue':''),p.due?(overdue?'已逾期 · ':'◷ ')+p.due.slice(5).replace('-',' / '):'未设截止日期'));const actions=node('div','card-actions');if(p.link&&/^https?:\/\//i.test(p.link)){const a=node('a','','↗');a.href=p.link;a.target='_blank';a.rel='noopener noreferrer';a.setAttribute('aria-label','打开'+p.name+'的链接');actions.append(a)}const edit=node('button','','✎');edit.setAttribute('aria-label','编辑'+p.name);edit.addEventListener('click',()=>openEditor(p));const del=node('button','','×');del.setAttribute('aria-label','删除'+p.name);del.addEventListener('click',()=>{deleting=p.id;$('confirm').showModal()});actions.append(edit,del);bottom.append(actions);c.append(bottom);return c}
function openEditor(p){editing=p?.id||null;$('form').reset();$('modalTitle').textContent=p?'编辑项目':'新建项目';for(const key of ['name','description','status','priority','due','link'])if(p)$(key).value=p[key];$('tags').value=p?p.tags.join(', '):'';$('completed').value=p?.completedAt||'';$('completed').max=today();$('completedLabel').hidden=$('status').value!=='done';$('editor').showModal();$('name').focus()}
$('add').onclick=()=>openEditor();$('emptyAdd').onclick=()=>openEditor();$('close').onclick=$('cancel').onclick=()=>$('editor').close();$('keep').onclick=()=>$('confirm').close();$('deleteConfirm').onclick=()=>{if(save(projects.filter(p=>p.id!==deleting))){$('confirm').close();toast('项目已删除')}};
$('form').onsubmit=e=>{e.preventDefault();const name=$('name').value.trim();if(!name){$('name').setCustomValidity('请输入项目名称');$('name').reportValidity();return}const link=$('link').value.trim();if(link&&!/^https?:\/\//i.test(link)){$('link').setCustomValidity('请使用 http 或 https 链接');$('link').reportValidity();return}if($('completed').value&&(!WeeklyReport.validDate($('completed').value)||$('completed').value>today())){toast('完成日期不能晚于今天');return}const p={id:editing||crypto.randomUUID(),name,description:$('description').value.trim(),status:$('status').value,priority:$('priority').value,due:$('due').value,completedAt:$('status').value==='done'?($('completed').value||null):null,tags:[...new Set($('tags').value.split(/[,，]/).map(t=>t.trim()).filter(Boolean))].slice(0,10),link,createdAt:editing?projects.find(p=>p.id===editing).createdAt:new Date().toISOString()};if(save(editing?projects.map(x=>x.id===editing?p:x):[p,...projects])){$('editor').close();toast(editing?'项目已更新':'新项目已创建')}};
$('name').oninput=()=>$('name').setCustomValidity('');$('link').oninput=()=>$('link').setCustomValidity('');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('search').oninput=render;
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,projects},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='拾序项目备份-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出')};$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('文件不能超过 2 MB');const data=JSON.parse(await file.text()),rows=Array.isArray(data)?data:data.projects;if(!Array.isArray(rows)||rows.length>1000||!rows.every(valid))throw Error('文件格式不正确，请选择本看板导出的 JSON 备份');const incoming=rows.map(p=>({...p,id:crypto.randomUUID(),createdAt:typeof p.createdAt==='string'?p.createdAt:new Date().toISOString()}));if(save([...incoming,...projects]))toast(`已导入 ${incoming.length} 个项目，原有项目已保留`)}catch(e){toast(e.message||'导入失败，请检查文件格式')}finally{$('file').value=''}};
window.addEventListener('storage',e=>{if(e.key===KEY){try{const rows=JSON.parse(e.newValue||'[]');if(Array.isArray(rows)&&rows.every(valid)){projects=rows;render();toast('已同步其他标签页的修改')}}catch{}}});render();

// Existing completed projects keep an unknown date until the user fills it in.
$('status').onchange=()=>{const done=$('status').value==='done';$('completedLabel').hidden=!done;$('completed').value=done?WeeklyReport.completedDate(editing?projects.find(p=>p.id===editing):null,'done')||'':''};
$('weekly').onclick=()=>{$('reportDate').value=today();$('reportText').value=WeeklyReport.generate(projects);$('report').showModal()};
$('closeReport').onclick=()=>$('report').close();
$('reportDate').onchange=()=>{if(!WeeklyReport.validDate($('reportDate').value)){$('reportDate').setCustomValidity('请选择有效日期');$('reportDate').reportValidity();return}$('reportDate').setCustomValidity('');$('reportText').value=WeeklyReport.generate(projects,$('reportDate').value)};
$('reportDate').oninput=()=>$('reportDate').setCustomValidity('');
$('copyReport').onclick=async()=>{try{await navigator.clipboard.writeText($('reportText').value);toast('周报已复制')}catch{$('reportText').focus();$('reportText').select();toast('无法自动复制，已选中全文，请手动复制')}};
$('downloadReport').onclick=()=>{const url=URL.createObjectURL(new Blob([$('reportText').value],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='个人项目周报-'+(WeeklyReport.validDate($('reportDate').value)?WeeklyReport.weekRange($('reportDate').value).start:today())+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('周报已下载')};
